describe("CA-12 freeze: shared numbers and MCP output equal base", () => {
  beforeAll(() => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(NOW);
  });
  afterAll(() => vi.useRealTimers());

  it("shared functions return the base values once only the new top-level fields are removed", () => {
    expect(canon(stripNew(sharedOutputs()))).toStrictEqual(GOLDEN.shared);
  });

  it("the fixture really walks the assumptions (guards the fixture, not the code)", () => {
    const segs = SEGMENTS as SegLike[];
    const acv = Object.fromEntries(
      segs.map((s) => [
        s.id,
        segmentAcv(
          s,
          DEALS.filter((d) => assignSegment(d, segs) === s.id),
        ).source,
      ]),
    );
    expect(acv).toMatchObject({
      "s-pyme": "ganados",
      "s-abiertos": "abiertos",
      "s-mid": "rango",
      "s-vacio": "rango",
      "s-medio": "rango",
    });
    expect(assignSegment(DEALS[0], segs)).toBe("s-pyme");
    expect(assignSegment(DEALS[2], segs)).toBe("s-pyme");
    const rows = segmentCoverage(
      segs,
      DEALS,
      TARGETS,
      RANGE,
      COSTS.filter((c) => c.period === Q),
    );
    const byId = Object.fromEntries(rows.map((r) => [r.segment.id, r]));
    expect(byId["s-cero"].payback.real).toBe(Infinity);
    expect(byId["s-neg"].payback.real).toBeLessThan(0);
    const q3 = segmentCac(
      COSTS.filter((c) => c.period === "2026-Q3"),
      {},
      segs.map((s) => s.id),
    );
    expect(q3["s-pyme"].shared).toBeCloseTo(600);
  });

  it("get_real_metrics returns exactly the base output (nothing removed)", async () => {
    expect(await run(realMetrics, {})).toStrictEqual(GOLDEN.realMetrics);
  });

  it("get_segment_coverage returns exactly the base output (nothing removed)", async () => {
    expect(await run(segmentCoverageTool, { quarter: Q })).toStrictEqual(
      GOLDEN.segmentCoverageTool,
    );
    expect(await run(segmentCoverageTool, {})).toStrictEqual(GOLDEN.segmentCoverageToolDefault);
  });
});
